```st
FUNCTION_BLOCK FB
VAR_INPUT
    runRequest      : BOOL;
    pressure        : REAL;
    pressureValid   : BOOL;
    fuelFlow        : REAL;
    steamFlow       : REAL;
    outletCmd       : INT;
    outletFeedback  : INT;
    resetBtn        : BOOL;
END_VAR

VAR_OUTPUT
    tripLatched      : BOOL;
    fuelPermit       : BOOL;
    currentCauseMask : WORD;
    latchedCauseMask : WORD;
    diagnosticActive : BOOL;
END_VAR

VAR
    lastResetBtn     : BOOL;
    consecStuckCount : INT;
    resetRising      : BOOL;
    tripCondition    : BOOL;
END_VAR

(* Detect rising edge of reset button *)
resetRising    := resetBtn AND NOT lastResetBtn;
lastResetBtn   := resetBtn;

(* Determine current diagnostic cause mask *)
IF NOT runRequest THEN
    currentCauseMask  := 0;
    consecStuckCount  := 0;
ELSE
    (* Bit0: pressure transmitter failure *)
    IF NOT pressureValid THEN
        currentCauseMask := WORD#1;            (* 1 << 0 *)
    ELSE
        currentCauseMask := WORD#0;
    END_IF

    (* Valve stuck detection (bit1) *)
    IF runRequest AND pressureValid AND (pressure >= 4500.0)
        AND (outletCmd >= 50) AND (outletFeedback <= 10) THEN
        consecStuckCount := consecStuckCount + 1;
    ELSE
        consecStuckCount := 0;
    END_IF

    IF consecStuckCount >= 3 THEN
        currentCauseMask := currentCauseMask OR WORD#2;   (* 1 << 1 *)
    END_IF

    (* Bit2: excess fuel (fuelFlow >= 4.0 and steamFlow <= 10.0) *)
    IF (fuelFlow >= 4.0) AND (steamFlow <= 10.0) THEN
        currentCauseMask := currentCauseMask OR WORD#4;   (* 1 << 2 *)
    END_IF

    (* Bit3: unidentified cause when overpressure but no other cause *)
    IF pressureValid AND (pressure >= 4500.0) AND (currentCauseMask = WORD#0) THEN
        currentCauseMask := currentCauseMask OR WORD#8;   (* 1 << 3 *)
    END_IF
END_IF

(* Trip condition: runRequest AND (pressureValid & overpressure OR pressureValid false) *)
tripCondition := runRequest AND ( (pressureValid AND (pressure >= 4500.0)) OR (NOT pressureValid) );

(* Set trip latch *)
IF tripCondition THEN
    tripLatched := TRUE;
END_IF

(* Reset handling *)
IF resetRising AND (NOT runRequest) AND pressureValid AND (pressure <= 4200.0) THEN
    tripLatched      := FALSE;
    latchedCauseMask := WORD#0;
    consecStuckCount := 0;
END_IF

(* Accumulate latched cause mask while trip is active *)
IF tripLatched THEN
    latchedCauseMask := latchedCauseMask OR currentCauseMask;
END_IF

(* Fuel permit *)
fuelPermit := runRequest AND NOT tripLatched;

(* Diagnostic active flag *)
diagnosticActive := (currentCauseMask <> WORD#0);
END_FUNCTION_BLOCK
```

